      "card_ids": ["C10"],
      "claim": "A closely related dichlorophenylpiperazine amide showed excellent brain penetrability in mice with brain-to-plasma ratios ranging from 6- to 20-fold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "An N-benzylpiperidine fluorobenzamide showed good brain uptake in mice, supporting CNS access for this amide/piperazine chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "A structurally similar chloroaryl amide P2X7 antagonist showed good CNS penetrability with a brain/plasma ratio of 1.3 in rats.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "A pyridyl-containing amide compound exhibited good brain exposure with plasma and brain concentrations equivalent, supporting CNS penetration for heteroaryl amides.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a close analogue of multiple dichlorophenylpiperazine amides with demonstrated high brain penetration, and all high-transfer experimental evidence supports meaningful CNS access.",
  "evidence_gaps": [
